(729,3302,'custom_css','.porto-tb-item .product-list-type .product-image { flex: 0 0 248px; margin: 0 20px 0 0; }\n.product-list-type .porto-tb-addcart { vertical-align: middle; }\n.product-list-type .porto-tb-addcart i::before { font-size: .9375rem; font-weight: 600; line-height: 21px; }\n.product-list-type .porto-tb-wishlist .add_to_wishlist i { margin: 0;}\n.product-list-type .porto-tb-wishlist span { display: none; }\n.product-list-type  .porto-tb-wishlist, .product-list-type  .porto-tb-quickview {\n    width: 35px;\n    display: inline-flex;\n    height: 35px;\n    line-height: 35px;\n    justify-content: center;\n    flex-direction: column;\n    text-align: center;\n    vertical-align: middle;\n}\n.product-list-type .porto-tb-wishlist .add_to_wishlist::before { content: none;}\n.product-list-type .porto-tb-wishlist .exists a { font-size: 0;}\n.product-list-type .porto-tb-wishlist .exists a::before { font-size: 16px; line-height: 17px;}\n.product-list-type .text-ellipsis { text-overflow: ellipsis; overflow: hidden; white-space: nowrap; }\n.product-list-type .product-excerpt { \n    overflow: hidden;\n    display: -webkit-box;\n    -webkit-line-clamp: 2;\n    -webkit-box-orient: vertical;\n}\n@media (max-width: 576px) {\n    .porto-tb-item .product-list-type  .product-image { flex: 0 0 100%; margin: 0 0 1rem; }\n    .product-list-type .porto-tb-addcart { font-size: 0; }\n    .product-list-type .porto-tb-addcart i { margin-right: 0;}\n    .product-list-type .product-list-type .product-list-content { padding: 1rem 0;  }\n}'),
(730,3302,'porto_blocks_style_options_css','.page-wrapper .porto-gb-5b46d2f90d5f865740741e61ad24ae22{padding-top:0px;padding-bottom:0px;}.page-wrapper .porto-gb-f1cfc59be95f2669394a25fe8aa4f6e7{}.page-wrapper .porto-gb-b9b55783bd04809d0f244fd9fb070aaa{padding-top:0px;padding-bottom:0px;padding-left:20px;}.page-wrapper .porto-gb-00a41a38463a2d36a51485aed7aa6867{width:100%;}.page-wrapper .porto-gb-00a41a38463a2d36a51485aed7aa6867{font-size:.625rem;--porto-fs:.625rem;text-transform:uppercase;line-height:1.7;--porto-lh:1.7;color:#777777}.page-wrapper .porto-gb-268dc36d191065b32487d75bd6b8813e{margin-bottom:0.4375rem;}.porto-gb-268dc36d191065b32487d75bd6b8813e,.porto-gb-268dc36d191065b32487d75bd6b8813e p{font-size:1.2857em;--porto-fs:1.2857em;font-weight:600;line-height:1.35;--porto-lh:1.35;letter-spacing:-.05em;text-align:left;}.page-wrapper .porto-gb-df0b4f12416401f7ef052cf276bc55c0{margin-top:0.625rem;margin-bottom:0.875rem;}.page-wrapper .porto-gb-70a7ab76a1ab83d1abbae56e6fa7aa1e{margin-bottom:1rem;width:100%;}.porto-gb-70a7ab76a1ab83d1abbae56e6fa7aa1e .price{font-size:1.125rem;--porto-fs:1.125rem;}.page-wrapper .porto-gb-67c53749f94ae2228ffb276ef8e9d224{border-style:solid;border-width:1px 1px 1px 1px;border-color:#dddddd;padding:6px 9px 6px 9px;box-shadow:none;}.page-wrapper .porto-gb-67c53749f94ae2228ffb276ef8e9d224:hover{background-color:rgba(28,95,168,1);color:#ffffff;box-shadow:none;}.page-wrapper .porto-gb-67c53749f94ae2228ffb276ef8e9d224{font-size:12px;--porto-fs:12px;font-weight:600;text-transform:uppercase;color:#383f48}.page-wrapper .porto-gb-114b2125ca7939c38f5fa78bb92790bc{background-color:rgba(255,255,255,1);border-style:solid;border-width:1px 1px 1px 1px;border-color:#dddddd;box-shadow:none;}.page-wrapper .porto-gb-114b2125ca7939c38f5fa78bb92790bc:hover{background-color:rgba(28,95,168,1);color:#ffffff;}.porto-gb-114b2125ca7939c38f5fa78bb92790bc{font-size:1rem;--porto-fs:1rem;line-height:35px;--porto-lh:35px;}.page-wrapper .porto-gb-80b5bede559b573f904ab